function validate([arr, mat]) {
  const m = mat.length;
  if (m < 1) return 'mat needs at least one row.';
  const n = mat[0].length;
  if (n < 1) return 'mat needs at least one column.';
  if (mat.some(row => row.length !== n)) return 'Every row of mat must have the same length.';
  const total = m * n;
  if (total > 100000) return 'm * n is at most 10^5.';
  if (arr.length !== total) return 'arr must have m * n values.';
  const seenArr = new Array(total + 1).fill(false);
  for (const v of arr) {
    if (!Number.isInteger(v) || v < 1 || v > total || seenArr[v]) return 'arr must hold each of 1 to m * n exactly once.';
    seenArr[v] = true;
  }
  const seenMat = new Array(total + 1).fill(false);
  for (const row of mat) for (const v of row) {
    if (!Number.isInteger(v) || v < 1 || v > total || seenMat[v]) return 'mat must hold each of 1 to m * n exactly once.';
    seenMat[v] = true;
  }
  return null;
}

