function firstCompleteIndex(arr, mat) {
  const when = [];
  arr.forEach((v, i) => { when[v] = i; });
  const m = mat.length, n = mat[0].length;
  let best = Infinity;
  for (let r = 0; r < m; r++) best = Math.min(best, Math.max(...mat[r].map(v => when[v])));
  for (let c = 0; c < n; c++) {
    let last = -1;
    for (let r = 0; r < m; r++) last = Math.max(last, when[mat[r][c]]);
    best = Math.min(best, last);
  }
  return best;
}

