function generate(rand, size) {
  const shuffle = list => { for (let i = list.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [list[i], list[j]] = [list[j], list[i]]; } return list; };
  let m, n;
  if (size === 'large') {
    const shapes = [[40, 50], [50, 40], [1, 2000], [2000, 1], [44, 45], [20, 100], [100, 20]];
    [m, n] = shapes[Math.floor(rand() * shapes.length)];
  } else {
    m = 1 + Math.floor(rand() * 4);
    n = 1 + Math.floor(rand() * 4);
  }
  const values = shuffle(Array.from({ length: m * n }, (_, i) => i + 1));
  const mat = Array.from({ length: m }, (_, r) => values.slice(r * n, r * n + n));
  const arr = shuffle(Array.from({ length: m * n }, (_, i) => i + 1));
  return [arr, mat];
}
